def breakSum(n):
    if n == 0:
        return 0

    # Memoization dictionary to store computed results
    memo = {}

    def helper(num):
        if num == 0:
            return 0

        # If already computed, return from memo
        if num in memo:
            return memo[num]

        # Calculate maximum sum by dividing into three parts
        max_sum = num  # Don't break and take the number as is
        for i in range(1, num // 3 + 1):
            part1 = helper(i)
            part2 = helper(num - i - i)  # This assumes we split into two equal parts and one remaining
            if part1 + part2 > max_sum:
                max_sum = part1 + part2

        memo[num] = max_sum
        return max_sum

    return helper(n)

